const t={klipperscreenStudio:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Bezpiecznie edytuj konfigurację ekranu dotykowego KlipperScreen, a następnie uruchom ponownie KlipperScreen, aby zastosować zmiany. Każdy zapis jest najpierw archiwizowany."}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Pomoc"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"O KlipperScreen Studio"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Zamknij"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"Jak czytać"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"Edytuj tekst konfiguracji poniżej (lub pozostaw bez zmian)."}},{t:0,b:{t:2,i:[{t:3}],s:"Zapisz — bieżący plik jest najpierw archiwizowany, a zapis jest odrzucany, gdy drukarka jest zajęta."}},{t:0,b:{t:2,i:[{t:3}],s:"Uruchom ponownie KlipperScreen, aby zastosować zmianę na fizycznym ekranie."}},{t:0,b:{t:2,i:[{t:3}],s:"Wiersze używają zakończeń UNIX (LF), wymuszanych automatycznie przy zapisie."}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Słownik"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Szybkie definicje używanych tu pojęć KlipperScreen."}}},config:{title:{t:0,b:{t:2,i:[{t:3}],s:"Czym jest karta Konfiguracja?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Surowy plik KlipperScreen.conf. Edytuj dowolne ustawienie ręcznie; zapis najpierw archiwizuje plik, jest odrzucany, gdy drukarka jest zajęta, i ostrzega, jeśli plik zmienił się na ekranie od czasu wczytania. Większość osób używa zamiast tego kart Ustawienia / Menu / Motywy."}}},settings:{title:{t:0,b:{t:2,i:[{t:3}],s:"Czym jest karta Ustawienia?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Najczęściej używane opcje [main] w formie formularza — motyw, język, usypianie ekranu, rozmiar czcionki i przełączniki. Wstępnie wypełnione z bieżącej konfiguracji; zapisywane są tylko zmienione opcje. Uruchom ponownie, aby zastosować."}}},menus:{title:{t:0,b:{t:2,i:[{t:3}],s:"Czym jest karta Menu?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Projektuj siatki przycisków ekranu dotykowego. Każde drzewo (__main to siatka główna, __print to ekran druku) zawiera swoje przyciski; dodawaj je, zmieniaj nazwy, kolejność i zagnieżdżaj, a każdy ustaw tak, aby otwierał podmenu, otwierał wbudowany ekran lub uruchamiał G-code."}}},themes:{title:{t:0,b:{t:2,i:[{t:3}],s:"Czym jest karta Motywy?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Zbuduj motyw KlipperScreen: wybierz kolor dla każdego tokena palety i promień zaokrąglenia, obserwuj podgląd na żywo, a następnie utwórz go i zastosuj na ekranie. Podgląd jest przybliżony — prawdziwy ekran renderuje w GTK."}}},kiosk:{title:{t:0,b:{t:2,i:[{t:3}],s:"Czym jest karta Kiosk?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Umieść samą aplikację FilaMind Flow na ekranie dotykowym jako przeglądarkę pełnoekranową — pełna kontrola nad tym, co pokazuje ekran. To odwracalna zamiana z KlipperScreen (domyślnie tymczasowa; ponowny rozruch przywraca KlipperScreen). Wymaga jednorazowego instalatora na hoście drukarki."}}}},glossary:{klipperScreen:{term:{t:0,b:{t:2,i:[{t:3}],s:"KlipperScreen"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Interfejs ekranu dotykowego działający na małym wyświetlaczu podłączonym do drukarki — oddzielny od tego panelu webowego."}}},theme:{term:{t:0,b:{t:2,i:[{t:3}],s:"Motyw"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Wygląd KlipperScreen — kolory, ikony i promień zaokrąglenia. Znajduje się w folderze styles/<name> na hoście; wyłącznie kosmetyczny (nie zmienia układu)."}}},menu:{term:{t:0,b:{t:2,i:[{t:3}],s:"Menu (__main / __print)"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Siatki przycisków pokazywane przez KlipperScreen. __main to ekran główny, __print to ekran wyświetlany podczas druku, __splashscreen to ekran startowy."}}},panel:{term:{t:0,b:{t:2,i:[{t:3}],s:"Panel"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Wbudowany ekran KlipperScreen, który może otworzyć przycisk (ruch, temperatura, ekstruzja, siatka stołu, …). Ich wewnętrzna zawartość jest ustalona przez KlipperScreen."}}},autoBlock:{term:{t:0,b:{t:2,i:[{t:3}],s:"Blok generowany automatycznie (#~#)"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Sekcja, którą KlipperScreen zapisuje sam dla siebie na dole pliku conf, po znaczniku #~#. FilaMind nigdy jej nie edytuje — tylko Twoje ustawienia powyżej."}}},kiosk:{term:{t:0,b:{t:2,i:[{t:3}],s:"Kiosk"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Uruchamianie przeglądarki pełnoekranowej na ekranie dotykowym zamiast KlipperScreen, aby ekran pokazywał FilaMind Flow. W pełni odwracalne."}}}}},status:{checking:{t:0,b:{t:2,i:[{t:3}],s:"Sprawdzanie KlipperScreen…"}},absent:{t:0,b:{t:2,i:[{t:3}],s:"Nie wykryto KlipperScreen na tej drukarce (brak KlipperScreen.conf i brak zgłoszenia przez Moonraker). Zainstaluj KlipperScreen, aby użyć tego narzędzia."}},present:{t:0,b:{t:2,i:[{t:3}],s:"Wykryto KlipperScreen"}},theme:{t:0,b:{t:2,i:[{t:3}],s:"Motyw"}},language:{t:0,b:{t:2,i:[{t:3}],s:"Język"}},notRestartable:{t:0,b:{t:2,i:[{t:3}],s:"Moonraker nie może automatycznie uruchomić ponownie KlipperScreen — uruchom go ręcznie po zapisaniu."}}},editor:{loading:{t:0,b:{t:2,i:[{t:3}],s:"Odczyt KlipperScreen.conf…"}},reload:{t:0,b:{t:2,i:[{t:3}],s:"Wczytaj ponownie"}},save:{t:0,b:{t:2,i:[{t:3}],s:"Zapisz konfigurację"}},saving:{t:0,b:{t:2,i:[{t:3}],s:"Zapisywanie…"}},saved:{t:0,b:{t:2,i:[{t:3}],s:"Zapisano (zarchiwizowano)"}},unsaved:{t:0,b:{t:2,i:[{t:3}],s:"Niezapisane zmiany"}}},save:{busy:{t:0,b:{t:2,i:[{t:3}],s:"Odrzucono, gdy drukarka jest zajęta — spróbuj ponownie, gdy będzie bezczynna."}},stale:{t:0,b:{t:2,i:[{t:3}],s:"KlipperScreen.conf zmienił się na dysku od czasu wczytania (prawdopodobnie edytowany na ekranie). Wczytaj ponownie przed zapisem, aby nie nadpisać tej zmiany."}}},view:{config:{t:0,b:{t:2,i:[{t:3}],s:"Konfiguracja"}},settings:{t:0,b:{t:2,i:[{t:3}],s:"Ustawienia"}},menus:{t:0,b:{t:2,i:[{t:3}],s:"Menu"}},themes:{t:0,b:{t:2,i:[{t:3}],s:"Motywy"}},kiosk:{t:0,b:{t:2,i:[{t:3}],s:"Kiosk"}},fmscreen:{t:0,b:{t:2,i:[{t:3}],s:"Ekran FilaMind"}}},settings:{loading:{t:0,b:{t:2,i:[{t:3}],s:"Wczytywanie ustawień…"}},intro:{t:0,b:{t:2,i:[{t:3}],s:"Najczęściej używane opcje wyświetlania KlipperScreen w formie formularza. Zapisywane są tylko zmienione opcje — reszta zachowuje bieżące wartości. Uruchom ponownie, aby zastosować."}},onlyChanged:{t:0,b:{t:2,i:[{t:3}],s:"Do KlipperScreen.conf zapisywane są tylko zmienione tu ustawienia."}},save:{t:0,b:{t:2,i:[{t:3}],s:"Zapisz ustawienia"}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:"Zapisano — uruchom ponownie KlipperScreen, aby zastosować."}},unset:{t:0,b:{t:2,i:[{t:3}],s:"Pozostaw nieustawione (domyślne)"}},never:{t:0,b:{t:2,i:[{t:3}],s:"Nigdy (zawsze włączony)"}},fontSize:{small:{t:0,b:{t:2,i:[{t:3}],s:"Mały"}},medium:{t:0,b:{t:2,i:[{t:3}],s:"Średni"}},large:{t:0,b:{t:2,i:[{t:3}],s:"Duży"}},max:{t:0,b:{t:2,i:[{t:3}],s:"Maks."}}},label:{theme:{t:0,b:{t:2,i:[{t:3}],s:"Motyw"}},language:{t:0,b:{t:2,i:[{t:3}],s:"Język"}},screen_blanking:{t:0,b:{t:2,i:[{t:3}],s:"Uśpij ekran po"}},font_size:{t:0,b:{t:2,i:[{t:3}],s:"Rozmiar czcionki"}},"24htime":{t:0,b:{t:2,i:[{t:3}],s:"Zegar 24-godzinny"}},use_dpms:{t:0,b:{t:2,i:[{t:3}],s:"Użyj DPMS do wygaszania ekranu"}},show_cursor:{t:0,b:{t:2,i:[{t:3}],s:"Pokaż kursor myszy"}},confirm_estop:{t:0,b:{t:2,i:[{t:3}],s:"Potwierdzaj przed zatrzymaniem awaryjnym"}},show_heater_power:{t:0,b:{t:2,i:[{t:3}],s:"Pokaż moc grzałki w %"}},autoclose_popups:{t:0,b:{t:2,i:[{t:3}],s:"Automatycznie zamykaj wyskakujące okna"}}}},kiosk:{loading:{t:0,b:{t:2,i:[{t:3}],s:"Sprawdzanie ekranu…"}},intro:{t:0,b:{t:2,i:[{t:3}],s:"Umieść samą aplikację FilaMind Flow na ekranie dotykowym jako przeglądarkę pełnoekranową — pełna kontrola nad tym, co pokazuje ekran. Zamienia się z KlipperScreen: uruchomienie jednego zatrzymuje drugi."}},current:{t:0,b:{t:2,i:[{t:3}],s:"Ekran teraz"}},mode:{kiosk:{t:0,b:{t:2,i:[{t:3}],s:"Kiosk FilaMind"}},klipperscreen:{t:0,b:{t:2,i:[{t:3}],s:"KlipperScreen"}},none:{t:0,b:{t:2,i:[{t:3}],s:"Żaden nie działa"}}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:"Kiosk jeszcze nie zainstalowany"}},setupHint:{t:0,b:{t:2,i:[{t:3}],s:"Uruchom to raz na hoście drukarki (instaluje przeglądarkę pełnoekranową + usługę kiosku):"}},persist:{t:0,b:{t:2,i:[{t:3}],s:"Ustaw jako domyślne przy rozruchu (w przeciwnym razie zamiana jest tymczasowa — ponowny rozruch przywraca drugi)."}},safety:{t:0,b:{t:2,i:[{t:3}],s:"Domyślnie tymczasowe: ponowny rozruch przywraca drugi. Jeśli ekran kiedykolwiek zgaśnie, przez SSH uruchom: sudo systemctl start KlipperScreen"}},switchBtn:{t:0,b:{t:2,i:[{t:3}],s:"Przełącz na FilaMind"}},restoreBtn:{t:0,b:{t:2,i:[{t:3}],s:"Przywróć KlipperScreen"}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"Odśwież"}},confirmSwitchTitle:{t:0,b:{t:2,i:[{t:3}],s:"Umieścić FilaMind na ekranie?"}},confirmRestoreTitle:{t:0,b:{t:2,i:[{t:3}],s:"Przywrócić KlipperScreen?"}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:"To zatrzymuje jedną usługę ekranu i uruchamia drugą. Nie wpływa na aktywny druk, ale ekran dotykowy zgaśnie na kilka sekund podczas przełączania."}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Zrób to"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Anuluj"}},switchedNote:{t:0,b:{t:2,i:[{t:3}],s:"FilaMind przejmuje ekran — powinien pojawić się za kilka sekund."}},restoredNote:{t:0,b:{t:2,i:[{t:3}],s:"KlipperScreen wraca — ekran powinien wkrótce powrócić."}}},menus:{loading:{t:0,b:{t:2,i:[{t:3}],s:"Wczytywanie menu…"}},intro:{t:0,b:{t:2,i:[{t:3}],s:"Zaprojektuj, co pokazuje ekran dotykowy: przyciski każdego menu, ich kolejność i działanie każdego z nich. Siatka ekranu głównego to drzewo __main; ekran druku to __print."}},addItem:{t:0,b:{t:2,i:[{t:3}],s:"Dodaj przycisk"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Brak elementów — dodaj jeden."}},up:{t:0,b:{t:2,i:[{t:3}],s:"Przesuń w górę"}},down:{t:0,b:{t:2,i:[{t:3}],s:"Przesuń w dół"}},addChild:{t:0,b:{t:2,i:[{t:3}],s:"Dodaj podelement"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"Usuń"}},name:{t:0,b:{t:2,i:[{t:3}],s:"Nazwa"}},icon:{t:0,b:{t:2,i:[{t:3}],s:"Ikona"}},action:{t:0,b:{t:2,i:[{t:3}],s:"Akcja"}},actSubmenu:{t:0,b:{t:2,i:[{t:3}],s:"Otwórz podmenu"}},actPanel:{t:0,b:{t:2,i:[{t:3}],s:"Otwórz ekran"}},actGcode:{t:0,b:{t:2,i:[{t:3}],s:"Uruchom G-code"}},panel:{t:0,b:{t:2,i:[{t:3}],s:"Ekran"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"G-code"}},enable:{t:0,b:{t:2,i:[{t:3}],s:"Pokaż, jeśli"}},save:{t:0,b:{t:2,i:[{t:3}],s:"Zapisz menu"}},newItem:{t:0,b:{t:2,i:[{t:3}],s:"Nowy przycisk"}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:"Menu zapisane — uruchom ponownie KlipperScreen, aby je zobaczyć."}}},themes:{loading:{t:0,b:{t:2,i:[{t:3}],s:"Wczytywanie motywów…"}},palette:{t:0,b:{t:2,i:[{t:3}],s:"Paleta"}},radius:{t:0,b:{t:2,i:[{t:3}],s:"Promień zaokrąglenia"}},preview:{t:0,b:{t:2,i:[{t:3}],s:"Podgląd na żywo"}},btn:{t:0,b:{t:2,i:[{t:3}],s:"Przycisk"}},previewWarn:{t:0,b:{t:2,i:[{t:3}],s:"ostrzeżenie"}},previewApprox:{t:0,b:{t:2,i:[{t:3}],s:"Przybliżony podgląd — prawdziwy ekran renderuje w GTK; drobne różnice są oczekiwane."}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"Nazwa nowego motywu"}},createApply:{t:0,b:{t:2,i:[{t:3}],s:"Utwórz i zastosuj"}},createOnly:{t:0,b:{t:2,i:[{t:3}],s:"Tylko utwórz"}},installed:{t:0,b:{t:2,i:[{t:3}],s:"Zainstalowane motywy"}},apply:{t:0,b:{t:2,i:[{t:3}],s:"Zastosuj"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"Usuń motyw"}},generated:{t:0,b:{t:2,i:[{t:3}],s:"Utworzony tutaj"}},created:{t:0,b:{t:2,i:[{t:3}],s:"Motyw utworzony. Zastosuj go z listy, a następnie uruchom ponownie."}},appliedRestart:{t:0,b:{t:2,i:[{t:3}],s:"Motyw ustawiony — uruchom ponownie KlipperScreen, aby go zobaczyć."}},previewTitle:{t:0,b:{t:2,i:[{t:3}],s:"Drukarka"}}},restart:{button:{t:0,b:{t:2,i:[{t:3}],s:"Uruchom ponownie KlipperScreen"}},restarting:{t:0,b:{t:2,i:[{t:3}],s:"Ponowne uruchamianie…"}},done:{t:0,b:{t:2,i:[{t:3}],s:"KlipperScreen uruchamia się ponownie — ekran wkrótce się przeładuje."}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:"Uruchomić ponownie KlipperScreen?"}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:"To uruchamia ponownie usługę ekranu dotykowego, aby zastosować zmiany. Nie wpłynie na aktywny druk, ale ekran zgaśnie na kilka sekund."}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Uruchom ponownie"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Anuluj"}}}}};export{t as default};
